insert into public.flashcard_catalogue_material (version_id,catalogue_id,catalogue_card_id,front,back,note_type,variant,tags,suspended,subdeck_path) select '1d7e067a-2fbb-4c5f-92a3-7f42e0e71166'::uuid,'AQA_ALEVEL_SOC_7192_EVIDENCE',i.id,x.f,x.b,'basic','forward',x.t,true,x.p from jsonb_to_recordset($j$[{"k":"ppp-soc-7192-evidence:7d9abf4e4eccc938347c","f":"Which development does ONS associate with falling birth rates in the 1970s?","b":"More widespread use of contraception","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (5) Demographic trends in the United Kingdom since 1900: birth rates, death rates, family size, life expectancy, ageing population, and migration and globalisation"},{"k":"ppp-soc-7192-evidence:dde71fffd7d113f4b704","f":"What social change does ONS give as one reason women began having first children later?","b":"Greater participation in higher education","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (5) Demographic trends in the United Kingdom since 1900: birth rates, death rates, family size, life expectancy, ageing population, and migration and globalisation"},{"k":"ppp-soc-7192-evidence:5c1b113f1bca53d68f43","f":"What public-health change helped reduce child deaths in the twentieth century?","b":"Mass vaccination programmes","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (5) Demographic trends in the United Kingdom since 1900: birth rates, death rates, family size, life expectancy, ageing population, and migration and globalisation"},{"k":"ppp-soc-7192-evidence:ba162fef47722706b3fc","f":"Which improvement in clean water and sewage systems did ONS list as a factor in rising life expectancy?","b":"Better sanitation","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (5) Demographic trends in the United Kingdom since 1900: birth rates, death rates, family size, life expectancy, ageing population, and migration and globalisation"},{"k":"ppp-soc-7192-evidence:75ba5f1870884b66a340","f":"Which political change coincided with increased EU net migration after 2004 according to ONS?","b":"Expansion of the European Union","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (5) Demographic trends in the United Kingdom since 1900: birth rates, death rates, family size, life expectancy, ageing population, and migration and globalisation"},{"k":"ppp-soc-7192-evidence:a923676df41a3868d19f","f":"How might falling child mortality affect the number of babies women have, according to ONS?","b":"Women may have fewer babies","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (5) Demographic trends in the United Kingdom since 1900: birth rates, death rates, family size, life expectancy, ageing population, and migration and globalisation"},{"k":"ppp-soc-7192-evidence:236b5a55bbf38e751038","f":"In Chambliss’s 1973 study, how did the delinquency rates of the Saints and Roughnecks compare?","b":"They were about equal","t":["PPP::Spec::AQA_SOC_4.3.1_b2","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper3","PPP::Topic::crime-and-deviance","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 3: Crime and deviance with theory and methods::Crime and deviance::4.3.1 (2) The social distribution of crime and deviance by ethnicity, gender and social class, including recent patterns and trends in crime"},{"k":"ppp-soc-7192-evidence:bd2339a9a98554c8f9dc","f":"What class-linked difference in police treatment did Chambliss report between the two groups?","b":"The lower-class Roughnecks faced more police attention and sanctions","t":["PPP::Spec::AQA_SOC_4.3.1_b2","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper3","PPP::Topic::crime-and-deviance","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 3: Crime and deviance with theory and methods::Crime and deviance::4.3.1 (2) The social distribution of crime and deviance by ethnicity, gender and social class, including recent patterns and trends in crime"},{"k":"ppp-soc-7192-evidence:c7cfff7544ebd5ce8745","f":"What limits generalising Chambliss’s findings to all social classes?","b":"He studied only two small groups in one high school community","t":["PPP::Spec::AQA_SOC_4.3.1_b2","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper3","PPP::Topic::crime-and-deviance","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 3: Crime and deviance with theory and methods::Crime and deviance::4.3.1 (2) The social distribution of crime and deviance by ethnicity, gender and social class, including recent patterns and trends in crime"},{"k":"ppp-soc-7192-evidence:69867fb7b032c7eb65e5","f":"What change does ONS identify as a cause of the large 1972 divorce-rate rise?","b":"The Divorce Reform Act 1969 made divorce easier upon separation","t":["PPP::Spec::AQA_SOC_4.2.2_b2","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (2) Changing patterns of marriage, cohabitation, separation, divorce, childbearing and the life course, including the sociology of personal life, and the diversity of contemporary family and household structures"},{"k":"ppp-soc-7192-evidence:b4f795b17ad3c284e9ea","f":"How large was the 2022–23 Attainment 8 score gap between Chinese pupils and White Gypsy or Roma pupils in England?","b":"45.2 points","t":["PPP::Spec::AQA_SOC_4.1.1_b2","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper1","PPP::Topic::education","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 1: Education with theory and methods::Education::4.1.1 (2) Differential educational achievement of social groups by social class, gender and ethnicity in contemporary society"},{"k":"ppp-soc-7192-evidence:0a9fb31dc654f3e1243d","f":"At the same 70th percentile of age-11 attainment, how large was the grammar-school admission chance gap between the most affluent and deprived family fifths?","b":"35 percentage points","t":["PPP::Spec::AQA_SOC_4.1.1_b4","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper1","PPP::Topic::education","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 1: Education with theory and methods::Education::4.1.1 (4) The significance of educational policies, including policies of selection, marketisation and privatisation, and policies to achieve greater equality of opportunity or outcome, for an understanding of the structure, role, impact and experience of and access to education; the impact of globalisation on educational policy"},{"k":"ppp-soc-7192-evidence:fdc24e66bfaad8b3f3c8","f":"Which early-years policy was shaped by research linking poverty with poor child outcomes?","b":"Sure Start","t":["PPP::Spec::AQA_SOC_4.1.3_b11","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper1","PPP::Topic::theory-and-methods","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 1: Education with theory and methods::Theory and methods::4.1.3 (11) The relationship between Sociology and social policy"},{"k":"ppp-soc-7192-evidence:af408c52a554df28f7fe","f":"How did the share of births registered to cohabiting parents in England and Wales change from 1986 to 2016?","b":"It rose from 10% to 32%","t":["PPP::Spec::AQA_SOC_4.2.2_b2","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (2) Changing patterns of marriage, cohabitation, separation, divorce, childbearing and the life course, including the sociology of personal life, and the diversity of contemporary family and household structures"},{"k":"ppp-soc-7192-evidence:04e072ae594dc01ca252","f":"How did the average age of first-time mothers in England and Wales change between 2006 and 2016?","b":"It rose from 27.3 to 28.8 years","t":["PPP::Spec::AQA_SOC_4.2.2_b2","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (2) Changing patterns of marriage, cohabitation, separation, divorce, childbearing and the life course, including the sociology of personal life, and the diversity of contemporary family and household structures"},{"k":"ppp-soc-7192-evidence:fad6c06f74f9664770c3","f":"How did the share of adults separated but still legally partnered in England and Wales change between 2011 and 2021?","b":"It fell from 2.6% to 2.2%","t":["PPP::Spec::AQA_SOC_4.2.2_b2","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (2) Changing patterns of marriage, cohabitation, separation, divorce, childbearing and the life course, including the sociology of personal life, and the diversity of contemporary family and household structures"},{"k":"ppp-soc-7192-evidence:c773aaf5e181e606c0c7","f":"What long-term trend did ONS report in the number of UK births since 1901?","b":"The number tended to decline, with substantial variation over time","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (5) Demographic trends in the United Kingdom since 1900: birth rates, death rates, family size, life expectancy, ageing population, and migration and globalisation"},{"k":"ppp-soc-7192-evidence:a13de26155dfdae6aad7","f":"In ONS’s analysis through 2018, how did death rates at all ages in 1901 compare with later rates?","b":"Death rates at all ages were much higher in 1901","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-level Sociology 7192 – Exam evidence::Paper 2: Topics in sociology::Families and households::4.2.2 (5) Demographic trends in the United Kingdom since 1900: birth rates, death rates, family size, life expectancy, ageing population, and migration and globalisation"},{"k":"ppp-soc-7192-evidence:9847fe6b9a34136e695b","f":"What was life expectancy at birth for men in England and Wales in 1901?","b":"About 45 years","t":["PPP::Spec::AQA_SOC_4.2.2_b5","PPP::AQA::7192","PPP::Deck::atomic","PPP::Paper::Paper2","PPP::Topic::families-and-households","PPP::Class::evidence"],"p":"AQA A-leve